type agreementNativeDiscardedAddressOwner struct {
	Field, Declaration, Root, Node, Code int
	Kind                                 string
}
type agreementNativeDiscardedAddressSource struct {
	Address             agreementNativeAddressSource
	Original, Projected agreementNativeProseAddressTree
	Lines, AfterLines   []string
}

// A folded name has no address authority when every occurrence is unused
// paragraph text or literal code, and at least one belongs to an unused root.
func agreementNativeDiscardedAddressOwners(part *agreementNativeAddressPart, tree *agreementNativeProseAddressTree) map[string][]agreementNativeDiscardedAddressOwner {
	out := make(map[string][]agreementNativeDiscardedAddressOwner)
	if !tree.Valid || len(tree.Trees) == 0 || len(tree.Trees[0]) == 0 || tree.Trees[0][0].Kind != "Document" || len(tree.Unanchorable) != len(part.Fields) {
		return out
	}
	groups := make(map[string][]int)
	for i, f := range part.Fields {
		groups[f.Folded] = append(groups[f.Folded], i)
	}
	for name, indices := range groups {
		var owners []agreementNativeDiscardedAddressOwner
		valid, discarded := true, false
		for _, i := range indices {
			owner, ok := agreementNativeDiscardedAddressFieldOwner(&part.Fields[i], tree)
			if !ok {
				valid = false
			}
			owner.Field = i
			discarded = discarded || owner.Declaration >= 0
			owners = append(owners, owner)
		}
		if valid && discarded {
			out[name] = owners
		}
	}
	return out
}
func agreementNativeDiscardedAddressFieldOwner(f *agreementNativeAddressField, tree *agreementNativeProseAddressTree) (agreementNativeDiscardedAddressOwner, bool) {
	owner := agreementNativeDiscardedAddressOwner{Declaration: -1, Root: -1, Node: -1, Code: -1}
	if f.Owner == -2 || f.Comment {
		return owner, false
	}
	for _, s := range tree.Comments {
		if s.Start < f.Token.Stop && f.Token.Start < s.Stop {
			return owner, false
		}
	}
	for di, d := range tree.Definitions {
		if d.Bounds.Span.Start >= f.Token.Stop || f.Token.Start >= d.Bounds.Span.Stop {
			continue
		}
		if owner.Declaration >= 0 || d.Root <= 0 || d.Root >= len(tree.Trees) || d.Node != 0 || !d.Found || d.Bounds.Span.Start > f.Token.Start || f.Token.Stop > d.Bounds.Span.Stop {
			return owner, false
		}
		nodes := tree.Trees[d.Root]
		if len(nodes) == 0 || nodes[0].Kind != "Footnote" || nodes[0].Depth != 0 {
			return owner, false
		}
		var path []string
		for ni, n := range nodes {
			if n.Depth < 0 || n.Depth > len(path) {
				return owner, false
			}
			path = append(slices.Clone(path[:n.Depth]), n.Kind)
			if !slices.Equal(path, []string{"Footnote", "Paragraph", "Text"}) || n.Raw {
				continue
			}
			for _, span := range n.Text {
				if span.Start <= f.Token.Start && f.Token.Stop <= span.Stop {
					if owner.Node >= 0 {
						return owner, false
					}
					owner.Declaration, owner.Root, owner.Node, owner.Kind = di, d.Root, ni, "Footnote"
				}
			}
		}
	}
	for ci, c := range tree.Code {
		if c.Span.Start >= f.Token.Stop || f.Token.Start >= c.Span.Stop {
			continue
		}
		if owner.Node >= 0 || owner.Code >= 0 || c.Span.Start > f.Token.Start || f.Token.Stop > c.Span.Stop || (c.Kind != "CodeSpan" && c.Kind != "CodeBlock" && c.Kind != "FencedCodeBlock") {
			return owner, false
		}
		owner.Code, owner.Kind = ci, c.Kind
	}
	return owner, owner.Node >= 0 || owner.Code >= 0
}
func agreementNativeDiscardedAddressShapes(part *agreementNativeAddressPart, tree *agreementNativeProseAddressTree) []agreementNativeAddressField {
	owners := agreementNativeDiscardedAddressOwners(part, tree)
	out := slices.Clone(part.Fields)
	for i := range out {
		f := &out[i]
		if len(owners[f.Folded]) == 0 {
			continue
		}
		raw := []byte(f.Raw)
		for at := f.Token.Start - f.Line.Start + 1; at < f.Token.Stop-f.Line.Start; at++ {
			raw[at] = '?'
		}
		f.Raw, f.Name, f.Folded = string(raw), "?", "?"
	}
	return out
}

// Capture every physical line after the native comment ranges remove their
// hidden bytes. Excerpt pairing reads this entire declared line, not a suffix.
func agreementNativeDiscardedAddressLines(body string, part *agreementNativeAddressPart, tree *agreementNativeProseAddressTree) []string {
	var lines []string
	for _, f := range part.Fields {
		if f.Line.Start < 0 || f.Line.Stop < f.Line.Start || f.Line.Stop > len(body) {
			return nil
		}
		at := f.Line.Start
		var shown strings.Builder
		for _, zone := range tree.Comments {
			if zone.Start < 0 || zone.Stop < zone.Start || zone.Stop > len(body) {
				return nil
			}
			start, stop := max(zone.Start, f.Line.Start), min(zone.Stop, f.Line.Stop)
			if start >= stop {
				continue
			}
			if start < at {
				return nil
			}
			shown.WriteString(body[at:start])
			at = stop
		}
		shown.WriteString(body[at:f.Line.Stop])
		lines = append(lines, shown.String())
	}
	return lines
}

// Same-width private names preserve the whole native tree, check reading and
// physical ledger even when the older strict declaration reading refuses.
func agreementNativeDiscardedAddressReading(body string) agreementNativeDiscardedAddressSource {
	r := agreementNativeDiscardedAddressSource{Address: agreementNativeAddressSource{Original: agreementNativeAddressPartReading(body)}}
	r.Original = agreementNativeProseAddressTreeReading(body, r.Address.Original.Fields)
	r.Lines = agreementNativeDiscardedAddressLines(body, &r.Address.Original, &r.Original)
	owners := agreementNativeDiscardedAddressOwners(&r.Address.Original, &r.Original)
	occupied := make(map[string]bool)
	for _, name := range r.Address.Original.Names {
		if strings.ContainsAny(name, "|#]\r\n") || strings.HasSuffix(name, "\\") {
			return r
		}
		occupied[name] = true
	}
	changed := make(map[string]string)
	private := []byte(body)
	for i := range r.Address.Original.Fields {
		f := &r.Address.Original.Fields[i]
		if len(owners[f.Folded]) == 0 {
			continue
		}
		name := changed[f.Folded]
		if name == "" {
			for _, ch := range []string{"q", "z", "v", "x", "w"} {
				candidate := "^" + strings.Repeat(ch, len(f.Name)-1)
				if !occupied[candidate] {
					name = candidate
					break
				}
			}
			if name == "" {
				return r
			}
			changed[f.Folded], occupied[name] = name, true
			r.Address.Changes = append(r.Address.Changes, agreementNativeAddressChange{Old: f.Folded, New: name})
		}
		if len(name) != f.Token.Stop-f.Token.Start {
			return r
		}
		copy(private[f.Token.Start:f.Token.Stop], name)
	}
	if len(r.Address.Changes) == 0 {
		return r
	}
	r.Address.Body = string(private)
	r.Address.Projected = agreementNativeAddressPartReading(r.Address.Body)
	r.Projected = agreementNativeProseAddressTreeReading(r.Address.Body, r.Address.Projected.Fields)
	r.AfterLines = agreementNativeDiscardedAddressLines(r.Address.Body, &r.Address.Projected, &r.Projected)
	r.Address.Shapes, r.Address.AfterShapes = agreementNativeDiscardedAddressShapes(&r.Address.Original, &r.Original), agreementNativeDiscardedAddressShapes(&r.Address.Projected, &r.Projected)
	r.Address.Valid = len(r.Lines) == len(r.Address.Original.Fields) && len(r.AfterLines) == len(r.Address.Projected.Fields) && cmp.Equal(r.Original, r.Projected) && cmp.Equal(r.Address.Shapes, r.Address.AfterShapes) && cmp.Equal(r.Address.Original.Native, r.Address.Projected.Native) && cmp.Equal(r.Address.Original.Check, r.Address.Projected.Check) && slices.Equal(r.Address.Original.Check.Targets, judge.LinkTargets(body)) && slices.Equal(r.Address.Projected.Check.Targets, judge.LinkTargets(r.Address.Body))
	return r
}

type agreementNativeDiscardedAddressPayload struct {
	Address      agreementNativeAddressPayload
	NativeSource agreementNativeDiscardedAddressSource
	Owners       map[string][]agreementNativeDiscardedAddressOwner
}

// Whole before/private receipts, ordered page membership and unchanged outside
// names must reproduce the unused-and-literal group's signed disagreement.
func agreementNativeDiscardedAddressEvidence(p *agreementNativeDiscardedAddressPayload) bool {
	s := &p.Address.Source
	a, w := agreementHTML{Blocks: p.Address.Blocks}, agreementHTML{Blocks: p.Address.WitnessBlocks}
	if len(p.NativeSource.Lines) != len(s.Original.Fields) || len(p.NativeSource.AfterLines) != len(s.Projected.Fields) || !s.Valid || len(s.Changes) == 0 || len(s.Original.Fields) != len(s.Projected.Fields) || !cmp.Equal(*s, p.NativeSource.Address) || !cmp.Equal(p.Owners, agreementNativeDiscardedAddressOwners(&s.Original, &p.NativeSource.Original)) || len(p.Owners) != len(s.Changes) || !cmp.Equal(p.Address.Names, agreementNativeAddressNames(s, &a, &w)) || len(p.Address.Original) != len(p.Address.Names) || len(p.Address.Witness) != len(p.Address.Names) || !cmp.Equal(p.Address.Signatures, agreementNativeAddressSignatures(p.Address.Original)) {
		return false
	}
	selected := make(map[string]string)
	nextOwners := agreementNativeDiscardedAddressOwners(&s.Projected, &p.NativeSource.Projected)
	if len(nextOwners) != len(p.Owners) {
		return false
	}
	visible := false
	for _, c := range s.Changes {
		old, ok := p.Address.Original[c.Old]
		next, has := p.Address.Witness[c.New]
		if !ok || !has || len(p.Owners[c.Old]) == 0 || !cmp.Equal(p.Owners[c.Old], nextOwners[c.New]) || p.Address.Original[c.New] != (agreementNativeAddressReceipt{}) || p.Address.Witness[c.Old] != (agreementNativeAddressReceipt{}) || old.Page != next.Page || old.Judge != next.Judge || old.Found != next.Found {
			return false
		}
		selected[c.Old], selected[c.New] = c.New, c.New
		if old.Page != old.Judge || old.Page != old.Found {
			visible = true
		}
		if old.Found {
			paired := false
			for _, o := range p.Owners[c.Old] {
				if agreementNativeReservationLine(old.Cut, p.NativeSource.Lines[o.Field]) && agreementNativeReservationLine(next.Cut, p.NativeSource.AfterLines[o.Field]) {
					paired = true
				}
			}
			if !paired {
				return false
			}
		}
	}
	if !visible {
		return false
	}
	expected := slices.Clone(p.Address.Blocks)
	for i, name := range expected {
		if renamed := selected[name]; renamed != "" {
			expected[i] = renamed
		}
	}
	if !cmp.Equal(expected, p.Address.WitnessBlocks) {
		return false
	}
	for _, name := range p.Address.Names {
		before, ok := p.Address.Original[name]
		after, has := p.Address.Witness[name]
		cut, found := render.Excerpt(p.Address.Body, name)
		wcut, wfound := render.Excerpt(s.Body, name)
		if !ok || !has || before.Page != slices.Contains(p.Address.Blocks, name) || after.Page != slices.Contains(p.Address.WitnessBlocks, name) || before.Cut != cut || before.Found != found || after.Cut != wcut || after.Found != wfound || (selected[name] == "" && before != after) {
			return false
		}
	}
	return true
}
func agreementNativeDiscardedAddressBudget(t *testing.T, body string, a *agreementHTML, fs []agreementFailure) agreementNativeDiscardedAddressPayload {
	t.Helper()
	source := agreementNativeDiscardedAddressReading(body)
	s := &source.Address
	if !s.Valid {
		return agreementNativeDiscardedAddressPayload{}
	}
	_, w := agreementIsolatedPage(t, agreementCase{Body: s.Body})
	names := agreementNativeAddressNames(s, a, &w)
	before, after := agreementNativeAddressPublic(t, body, a, names), agreementNativeAddressPublic(t, s.Body, &w, names)
	p := agreementNativeDiscardedAddressPayload{Address: agreementNativeAddressPayload{Body: body, Source: *s, Names: names, Blocks: slices.Clone(a.Blocks), WitnessBlocks: slices.Clone(w.Blocks), Original: before, Witness: after, Signatures: agreementNativeAddressSignatures(before)}, NativeSource: source, Owners: agreementNativeDiscardedAddressOwners(&s.Original, &source.Original)}
	if !agreementNativeDiscardedAddressEvidence(&p) || !cmp.Equal(p.Address.Signatures, agreementNativeAddressCurrent(fs)) {
		return agreementNativeDiscardedAddressPayload{}
	}
	return p
}
func agreementNativeDiscardedAddressDifference(c agreementCase, f *agreementFailure, a *agreementHTML, fs []agreementFailure, p *agreementNativeDiscardedAddressPayload) (kind, authority, wrong string) {
	if c.Body != p.Address.Body || c.Title != "" || len(c.Companions) != 0 || f.Property != "P3" || f.Identity != "block-three-way" || f.Tuple != (agreementCitation{}) || f.Multiplicity != 1 || p.Address.Signatures[agreementSignature(f)] != 1 || len(p.Owners[f.Fragment]) == 0 {
		return "", "", ""
	}
	if !cmp.Equal(p.NativeSource, agreementNativeDiscardedAddressReading(c.Body)) || !cmp.Equal(p.Address.Blocks, a.Blocks) || !cmp.Equal(p.Address.Signatures, agreementNativeAddressCurrent(fs)) || !agreementNativeDiscardedAddressEvidence(p) {
		return "", "", ""
	}
	r := p.Address.Original[f.Fragment]
	var faces []string
	if r.Page {
		faces = append(faces, "page")
	}
	if r.Judge {
		faces = append(faces, "judge")
	}
	if r.Found {
		faces = append(faces, "excerpt")
	}
	if len(faces) == 0 {
		return "", "", ""
	}
	return "debt", "#1011 stage 5", strings.Join(faces, "+")
}

