// Unaddressed words still belong to the captured body when all native facts and
// every public fragment receipt remain identical.
func TestAgreementNativeDiscardedAddressBody(t *testing.T) {
	t.Parallel()
	rich := agreementNativeDiscardedAddressControls()[102].Body
	c := agreementCase{Body: "ghost\n\n" + rich}
	other := agreementCase{Body: "shade\n\n" + rich}
	_, a := agreementIsolatedPage(t, c)
	_, w := agreementIsolatedPage(t, other)
	fs := agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{a})[0]
	changed := agreementFragmentFailures(t, []agreementCase{other}, []agreementHTML{w})[0]
	p := agreementNativeDiscardedAddressBudget(t, c.Body, &a, fs)
	q := agreementNativeDiscardedAddressBudget(t, other.Body, &w, changed)
	if p.Address.Body == "" || q.Address.Body == "" || p.Address.Body == q.Address.Body {
		t.Fatal("discarded address body control lacks distinct qualified bodies")
	}
	facts := func(p *agreementNativeDiscardedAddressPayload) []any {
		s := &p.Address.Source
		return []any{s.Original, s.Projected, s.Changes, s.Shapes, s.AfterShapes, p.NativeSource.Original, p.NativeSource.Projected, p.NativeSource.Lines, p.NativeSource.AfterLines, p.Owners, p.Address.Names, p.Address.Blocks, p.Address.WitnessBlocks, p.Address.Original, p.Address.Witness, p.Address.Signatures}
	}
	if !cmp.Equal(facts(&p), facts(&q)) {
		t.Fatal("discarded address body control changed declaration facts or public receipts")
	}
	var failure *agreementFailure
	for i := range changed {
		f := &changed[i]
		if k, _, _ := agreementNativeDiscardedAddressDifference(other, f, &w, changed, &q); k != "" {
			failure = f
			break
		}
	}
	if failure == nil {
		t.Fatal("discarded address body control is unowned")
	}
	p.Address.Body = other.Body
	if k, _, _ := agreementNativeDiscardedAddressDifference(other, failure, &w, changed, &p); k != "" {
		t.Fatal("caught: discarded address borrowed different bytes with identical declared facts")
	}
}
