// and literal comment markers, before an excerpt is considered.
func TestAgreementNativeDiscardedAddressLines(t *testing.T) {
	t.Parallel()
	body := "pre %%one%% ^a tail\nsecond <!--two--> ^b end\r\n"
	span := func(start, stop int) graph.Span { return graph.Span{Start: start, Stop: stop} }
	fields := []agreementNativeAddressField{{Line: span(0, 19)}, {Line: span(20, 46)}}
	comments := []graph.Span{span(4, 11), span(27, 37)}
	tests := []struct {
		name, body string
		fields     []agreementNativeAddressField
		comments   []graph.Span
		want       []string
	}{
		{"all physical lines", body, fields, comments, []string{"pre  ^a tail", "second  ^b end\r\n"}},
		{"whole hidden line", body, fields, []graph.Span{span(0, 19)}, []string{"", "second <!--two--> ^b end\r\n"}},
		{"comment clips both complete fields", body, fields, []graph.Span{span(12, 41)}, []string{"pre %%one%% ", "end\r\n"}},
		{"outside field comments", body, fields, []graph.Span{span(19, 20)}, []string{"pre %%one%% ^a tail", "second <!--two--> ^b end\r\n"}},
		{"empty comment span", body, fields, []graph.Span{span(3, 3)}, []string{"pre %%one%% ^a tail", "second <!--two--> ^b end\r\n"}},
		{"every disjoint comment", body, fields, []graph.Span{span(0, 3), span(4, 11), span(27, 37)}, []string{"  ^a tail", "second  ^b end\r\n"}},
		{"negative physical line", body, []agreementNativeAddressField{{Line: span(-1, 18)}}, comments, nil},
		{"reversed physical line", body, []agreementNativeAddressField{{Line: span(18, 0)}}, comments, nil},
		{"physical line outside body", body, []agreementNativeAddressField{{Line: span(0, 47)}}, comments, nil},
		{"negative native comment", body, fields, []graph.Span{span(-1, 2)}, nil},
		{"reversed native comment", body, fields, []graph.Span{span(10, 2)}, nil},
		{"native comment outside body", body, fields, []graph.Span{span(1, 47)}, nil},
		{"overlapping comment ledger", body, fields, []graph.Span{span(4, 11), span(8, 13)}, nil},
		{"unordered intersecting comments", body, fields, []graph.Span{span(12, 14), span(4, 11)}, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			part := agreementNativeAddressPart{Fields: tc.fields}
			tree := agreementNativeProseAddressTree{Comments: tc.comments}
			if diff := cmp.Diff(tc.want, agreementNativeDiscardedAddressLines(tc.body, &part, &tree)); diff != "" {
				t.Fatalf("caught: complete declared visible line ledger (-want +got):\n%s", diff)
			}
		})
	}
	t.Run("native literal comment protection", func(t *testing.T) {
		t.Parallel()
		s := agreementNativeDiscardedAddressReading("[^unused]: words ^a\n\n```\n%%literal%% words ^a\n```\n")
		if !s.Address.Valid || len(s.Original.Comments) != 0 || len(s.Original.Code) != 1 {
			t.Fatal("literal marker control lacks complete native roles")
		}
		if diff := cmp.Diff([]string{"[^unused]: words ^a", "%%literal%% words ^a"}, s.Lines); diff != "" {
			t.Fatalf("caught: native literal bytes in every original line (-want +got):\n%s", diff)
		}
		if diff := cmp.Diff([]string{"[^unused]: words ^q", "%%literal%% words ^q"}, s.AfterLines); diff != "" {
			t.Fatalf("caught: native literal bytes in every private line (-want +got):\n%s", diff)
		}
	})
}
